{
  "reviews": {
    "node-1pbq4gz": {
      "supported": false,
      "issue": "The node label asserts a normal pressure band at P-R and that the gallery serves RHOB; however, source b678a928-a8d2-472d-bc03-2e1a3dc411e6#1 explicitly states it is not a current piping diagram and does not establish valve positions or pressure available at any given time. The node relies on inference from context rather than explicit measurement, violating the requirement that every condition be supported by direct evidence.",
      "evidenceNeeded": "A record showing an actual numeric pressure reading for P-R in RHOB during Turn 2 prior to ~10:00 AM (or a statement confirming normal operation at issue time).",
      "question": "What is the recorded value or status of local indication P-R in RHOB between 08:10 and 09:45 on May 20, 2024?"
    },
    "node-1dzzqd8": {
      "supported": false,
      "issue": "The node claims no engineering disposition or temporary instruction was attached for changes between March 1 and May 20. Source 0ff450fe-49da-4c67-8b42-35449fdad35c#1 states that draft preparation alone does not satisfy distribution, but no evidence confirms whether a service-routing change actually occurred for this case or what disposition was attached. The claim remains proposed without confirmation of application.",
      "evidenceNeeded": "A record showing the engineering disposition status (revised ECP or approved temporary instruction) applicable to any instrument-air routing changes affecting RHOB between 2024-03-01 and May 20, 2024.",
      "question": "Was there an issued engineering disposition or approved temporary instruction for any service-routing change affecting the RHOB boundary prior to incident time?"
    },
    "node-psncku": {
      "supported": false,
      "issue": "The node asserts that a blank attachment field indicates no evidence of recent changes. Source eaee59fe-70f4-4876-a21d-780814412078#1 confirms the temporary instruction field was blank but does not establish whether an approved temporary instruction existed elsewhere or if a change occurred without attachment. A blank field alone cannot prove absence of routing changes.",
      "evidenceNeeded": "A record showing whether any service-routing change affecting RHOB had been documented with engineering disposition, regardless of where the approval appeared (ECP revision vs attached temporary instruction).",
      "question": "Was there an approved temporary instruction or revised ECP for instrument-air routing that affected RHOB between March 1 and May 20?"
    }
  },
  "decision": {
    "summary": "All three condition nodes are unsupported because they rely on inference rather than direct evidence. The incident description, shift log, and work package cover confirm the timing of preparation but do not establish pressure status or routing change documentation.",
    "evidenceUsed": ["incident-description", "eaee59fe-70f4-4876-a21d-780814412078#1", "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"],
    "unknowns": ["Actual pressure reading at P-R prior to incident", "Whether a service-routing change occurred and its disposition status", "Whether an approved temporary instruction existed for RHOB routing changes"],
    "alternatives": [
      "The air interruption may have originated upstream without any documented routing change.",
      "A recent routing change may exist but was not attached or revised, violating IA-D03 Section 3.6."
    ],
    "confidence": 0.95
  }
}
